script:
frappe.ui.form.on("Instructor Availability", {
    validate(frm) {
        const start = frm.doc.from_time;
        const end = frm.doc.to_time;

        if (start && end && start >= end) {
            frappe.throw("Giờ kết thúc phải sau giờ bắt đầu.");
        }
    }
});

function ling_group_instructor_query(frm) {
    frm.set_query("instructor", "instructors", (doc, child_doctype, child_name) => {
        const other_instructors = (doc.instructors || [])
            .filter(row => row.name !== child_name && row.instructor)
            .map(row => row.instructor);

        return other_instructors.length
            ? { filters: { name: ["not in", other_instructors] } }
            : {};
    });
}

frappe.ui.form.on("Student Group", {
    setup: ling_group_instructor_query,
    refresh: ling_group_instructor_query
});

frappe.ui.form.on("Student Group Instructor", {
    instructors_add: ling_group_instructor_query
});

function ling_set_instructor_query(frm) {
    frm.set_query("instructor", () => ({
        query: "education.ling_scheduling.instructor_query",
        filters: {
            student_group: frm.doc.student_group,
            schedule_date: frm.doc.schedule_date,
            from_time: frm.doc.from_time,
            to_time: frm.doc.to_time,
            current_schedule: frm.is_new() ? "" : frm.doc.name
        }
    }));
}

frappe.ui.form.on("Course Schedule", {
    setup(frm) {
        // The standard Education onload handler also reads this array.
        frm.instructors = frm.instructors || [];
    },
    onload_post_render: ling_set_instructor_query,
    refresh: ling_set_instructor_query,
    student_group: ling_set_instructor_query,
    schedule_date: ling_set_instructor_query,
    from_time: ling_set_instructor_query,
    to_time: ling_set_instructor_query
});

frappe.ui.form.on("IELTS Placement Test", {
    refresh(frm) {
        frm.add_custom_button("Tính band", () => {
            const fields = [
                "listening",
                "reading",
                "writing",
                "speaking"
            ];

            const scores = fields.map(
                field => Number(frm.doc[field])
            );

            const invalid = scores.some(
                score => !Number.isFinite(score) || score < 0 || score > 9
            );

            if (invalid) {
                frappe.throw("Điểm mỗi kỹ năng phải từ 0 đến 9.");
            }

            const average = scores.reduce(
                (total, score) => total + score, 0
            ) / 4;

            const band = Math.round(average * 2) / 2;

            frm.set_value("overall_band", band);
        });
    }
});
